theme.css:
/* ==== INTERFACE ====
token  --bg #F4F6F8         全局浅冷灰背景｜画布底
token  --panel-bg #FFFFFF   白底容器卡片｜面板底
token  --text #16202C       深墨靛黑｜所有正文与标题
token  --muted #5C6E82      深冷蓝灰｜次级成句、图注、刻度、结构边框线
token  --line #CBD5E1       浅冷灰细线｜内嵌分割线与非激活线
token  --primary #1B4E89    深群青｜主分类器、+1正类样本、确认操作
token  --class-neg #546577  石青深灰｜-1负类样本、次级数据
token  --accent #C0371E     赤朱红｜错误分类样本、权重放大、关键警示
token  --focus #C0371E      高亮轮廓色｜键盘与交互焦点
token  --fs-h1 34px         讲义一级主标题
token  --fs-h2 22px         内容区块与模块标题
token  --fs-lead 19px       核心概念先导段落
token  --fs-body 18px       基础阐述成句正文
token  --fs-sec 16px        次要解释与解说句
token  --fs-label 15px      图表标签与控件文本
token  --fs-tick 13px       坐标系纯数字刻度
版心   1488×844            #stage 预扣内边距 (1600×900)
版式   .single             单一居中聚焦主区
版式   .cols               经典左右对照主区
版式   .rows               上下分步结构主区
组件   .panel              实心背景仪器与对照容器
组件   .panel.q            透明带框提问与对比容器
组件   .big                等宽大数字指示器 (.sm/.lg 可选)
组件   .num                单值指标文本
组件   .unit               数字跟随物理/数学单位
组件   .ctl                输入控制包装容器
组件   .btn                标准动作按钮
组件   .btns               横向并列按钮组
组件   .hint               下沿操作提示文字
组件   .tag                样本标记与类别徽标
组件   .legend             图例列表 (.li, .sw, .sw.line)
组件   .cvbox              图表/Canvas隔离视口
组件   .quiz               测验与选择容器 (.opt, .fb)
组件   .lead               导言字号文本段
组件   .small              次级小字文本段
组件   .note               注释与边界条件提醒
==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;
  --bg: #F4F6F8;
  --panel-bg: #FFFFFF;
  --text: #16202C;
  --muted: #5C6E82;
  --line: #CBD5E1;
  --primary: #1B4E89;
  --class-neg: #546577;
  --accent: #C0371E;
  --focus: #C0371E;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --font-sans: "PingFang SC", "Hiragino Sans GB", "Noto Sans CJK SC", "Microsoft YaHei", -apple-system, sans-serif;
  --font-num: "SF Pro Text", "Helvetica Neue", "Segoe UI", Arial, sans-serif;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  box-sizing: border-box;
}

/* --- 字体与文本语义 --- */
.h1 { font-size: var(--fs-h1); font-weight: 700; line-height: 1.25; margin: 0 0 12px; color: var(--text); letter-spacing: -0.01em; }
.h2 { font-size: var(--fs-h2); font-weight: 600; line-height: 1.3; margin: 0 0 8px; color: var(--text); }
.lead { font-size: var(--fs-lead); line-height: 1.45; color: var(--text); margin: 0 0 16px; }
.body { font-size: var(--fs-body); line-height: 1.5; color: var(--text); margin: 0; }
.sec { font-size: var(--fs-sec); line-height: 1.45; color: var(--muted); margin: 0; }
.small { font-size: var(--fs-sec); line-height: 1.4; color: var(--muted); margin: 0; }
.note { font-size: var(--fs-sec); line-height: 1.4; color: var(--muted); border-left: 3px solid var(--muted); padding-left: 10px; }

/* --- 布局几何 --- */
.single { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.cols { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; flex: 1; min-height: 0; }
.rows { display: flex; flex-direction: column; gap: 18px; flex: 1; min-height: 0; }

/* --- 容器组件 --- */
.panel {
  background-color: var(--panel-bg);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 20px;
  box-sizing: border-box;
}
.panel.q {
  background-color: transparent;
  border: 1px dashed var(--muted);
  border-radius: 6px;
  padding: 20px;
  box-sizing: border-box;
}

/* --- 数值与度量 --- */
.num {
  font-family: var(--font-num);
  font-variant-numeric: tabular-nums;
}
.big {
  font-family: var(--font-num);
  font-size: 38px;
  font-weight: 700;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}
.big.sm { font-size: 28px; }
.big.lg { font-size: 52px; }
.unit {
  font-size: var(--fs-label);
  font-weight: 400;
  color: var(--muted);
  margin-left: 4px;
}

/* --- 控件与按钮 --- */
.ctl {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: var(--fs-label);
  color: var(--text);
}
.ctl input[type="range"] {
  accent-color: var(--primary);
  flex: 1;
  cursor: pointer;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 500;
  padding: 8px 16px;
  border-radius: 4px;
  border: 1px solid var(--muted);
  background-color: var(--panel-bg);
  color: var(--text);
  cursor: pointer;
  user-select: none;
}
.btn:hover {
  background-color: var(--bg);
  border-color: var(--text);
}
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.btn.active, .btn[aria-pressed="true"] {
  background-color: var(--primary);
  color: #FFFFFF;
  border-color: var(--primary);
}
.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.btns {
  display: flex;
  gap: 8px;
  align-items: center;
}
.hint {
  font-size: var(--fs-label);
  color: var(--muted);
  line-height: 1.35;
}

/* --- 状态标签与图例 --- */
.tag {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: var(--fs-label);
  font-weight: 600;
  line-height: 1.2;
}
.tag.pos { background-color: rgba(27, 78, 137, 0.12); color: var(--primary); }
.tag.neg { background-color: rgba(84, 101, 119, 0.12); color: var(--class-neg); }
.tag.warn { background-color: rgba(192, 55, 30, 0.12); color: var(--accent); }

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  font-size: var(--fs-label);
  color: var(--text);
}
.legend .li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.legend .sw {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  display: inline-block;
}
.legend .sw.line {
  width: 16px;
  height: 2px;
  border-radius: 0;
}

/* --- 图形与画布容器 --- */
.cvbox {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 4px;
  overflow: hidden;
  box-sizing: border-box;
}

/* --- 作答与选择 --- */
.quiz {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.opt {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border: 1px solid var(--line);
  background-color: var(--panel-bg);
  border-radius: 4px;
  font-size: var(--fs-body);
  color: var(--text);
  cursor: pointer;
  text-align: left;
}
.opt:hover {
  background-color: var(--bg);
  border-color: var(--muted);
}
.opt:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.opt.selected {
  border-color: var(--primary);
  background-color: rgba(27, 78, 137, 0.06);
}
.opt.correct {
  border-color: var(--primary);
  font-weight: 600;
}
.opt.wrong {
  border-color: var(--accent);
  font-weight: 600;
}
.fb {
  font-size: var(--fs-sec);
  line-height: 1.4;
  padding: 10px 14px;
  border-radius: 4px;
  margin-top: 6px;
  background-color: rgba(92, 110, 130, 0.08);
  color: var(--text);
}

svg .bar, svg .cell, svg .box { width:auto; height:auto; }
